            text-transform: uppercase;
            color: #A7B7CB;
            white-space: nowrap;
        }
        .rv-story i { font-size: 9px; color: #1051DF; opacity: .7; }
        .rv-stars { display: inline-flex; align-items: center; gap: 3px; font-size: 11px; flex-shrink: 0; }

        .rv-quote {
            flex: 1 1 auto;
            font-size: 13.5px;
