        .nav-ind {
            position: absolute;
            left: 0;
            bottom: -1px;
            height: 2px;
            width: 0;
            border-radius: 2px;
            background: #1051DF;
            opacity: 0;
            pointer-events: none;
            z-index: 2;
            will-change: transform, width;
            transition: transform .34s cubic-bezier(.4, 0, .2, 1),
                        width .34s cubic-bezier(.4, 0, .2, 1),
                        opacity .18s ease,
                        background-color .3s ease;
        }
        .nav-ind.is-ready { opacity: 1; }
