        .rvw-modal-box { position: relative; width: min(400px, 100%); background: #fff; border-radius: 18px;
            padding: 26px 24px; text-align: center; box-shadow: 0 30px 80px rgba(0,0,0,.35);
            animation: rvwpop .28s cubic-bezier(.2,.9,.3,1.2); }
