            display: grid; grid-template-columns: minmax(0,.9fr) minmax(0,1.1fr);
            align-items: stretch; gap: 0;
            border-radius: 26px; overflow: hidden;
            background:
                radial-gradient(900px 380px at 0% 0%, rgba(27,135,247,.18), transparent 62%),
                linear-gradient(180deg, rgba(16,50,92,.78) 0%, rgba(10,34,64,.92) 100%);
            border: 1px solid rgba(120,175,255,.18);
            box-shadow: 0 1px 0 rgba(190,220,255,.06) inset, 0 18px 40px rgba(2,12,28,.40);
        }
        .rvx-hero-media{
