        .rvx-highlight-who b{ font-size: 13px; font-weight: 700; color: #EAF2FF; }
        .rvx-highlight-who small{ font-size: 11.5px; color: #8AA6C6; }
        .rvx-highlight-who .rvx-stars{ margin-left: auto; }

        /* ---------- 2. featured intro ---------- */
        .rvx-featured{
            display: grid; grid-template-columns: minmax(0,1.25fr) minmax(0,1fr);
            gap: 22px; align-items: center; margin-top: 22px;
            padding: 22px; border-radius: 26px;
            background: linear-gradient(180deg, rgba(16,50,92,.55) 0%, rgba(10,34,64,.82) 100%);
            border: 1px solid rgba(120,175,255,.16);
