        .rvx-featured-media img{ width: 100%; height: 100%; object-fit: cover; display: block; }
        .rvx-featured-media::after{
            content: ""; position: absolute; inset: 0; pointer-events: none;
            background: linear-gradient(180deg, rgba(8,32,60,0) 45%, rgba(6,24,45,.85) 100%);
        }
