            padding: 7px 12px; border-radius: 999px;
            font-size: 11px; font-weight: 600; color: #DCEAFA;
            background: rgba(8,29,54,.78);
            border: 1px solid rgba(120,175,255,.24);
            -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px);
        }
