            border: 1px solid rgba(120,175,255,.12);
            animation: rvxShimmer 1.4s linear infinite;
        }
        @keyframes rvxShimmer{ from{ background-position: 160% 0; } to{ background-position: -60% 0; } }
        .rvx-empty{
