        .rvx-form-head{ display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
        .rvx-form-head h2{ margin: 0; font-size: clamp(1.2rem, 2.2vw, 1.55rem); font-weight: 800; letter-spacing: -.03em; color: #EAF2FF; }
