            box-shadow: 0 0 0 3px rgba(27,135,247,.18);
        }
        .rvx-textarea{ min-height: 120px; resize: vertical; line-height: 1.7; }
        .rvx-counter{ align-self: flex-end; font-size: 11px; color: #7C96B8; }

        /* star picker */
        .rvx-rate-wrap{ display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
        .rvx-rate{ display: inline-flex; gap: 6px; }
        .rvx-rate button{
            width: 42px; height: 42px; border-radius: 13px; cursor: pointer;
            display: grid; place-items: center;
            font-size: 17px; color: rgba(148,178,214,.35);
            background: rgba(8,32,60,.60);
            border: 1px solid rgba(120,175,255,.20);
            transition: transform .15s ease, color .15s ease, border-color .15s ease, background .15s ease;
        }
