        .rvx-rate button.on{
            color: #F5B301; background: rgba(245,179,1,.14); border-color: rgba(245,179,1,.45);
        }
        .rvx-rate button:focus-visible{ outline: 2px solid #1B87F7; outline-offset: 2px; }
        .rvx-rate-label{ font-size: 12.5px; font-weight: 600; color: #A9C4E4; }

