        /* ---------- success modal ---------- */
        .rvx-modal{ position: fixed; inset: 0; z-index: 9995; display: grid; place-items: center; padding: 20px; }
        .rvx-modal[hidden]{ display: none; }
        .rvx-modal-bd{ position: absolute; inset: 0; background: rgba(4,16,32,.72); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); }
        .rvx-modal-box{
            position: relative; width: min(440px, 100%);
            padding: 34px 28px 26px; border-radius: 24px; text-align: center;
            background: linear-gradient(180deg, rgba(16,50,92,.98) 0%, rgba(9,31,58,.99) 100%);
            border: 1px solid rgba(120,175,255,.26);
            box-shadow: 0 30px 70px rgba(2,10,24,.65);
            animation: rvxIn .3s ease both;
        }
        .rvx-modal-tick{
